/// <summary>
/// MPJ_5046_MetpayInterfaces 05/05/2021
/// Subtask class created to process all sub task process
/// </summary>
public class METVendOpenItemsSubTaskService
{
    str                                 errorMessage;
    str                                 infologMessage;


}

Method.Source:
    /// <summary>
    /// MPJ_5046_MetpayInterfaces 05/05/2021
    /// processSubTask contains the business logic to create/update according to the task and its parameters
    /// </summary>
    /// <param name = "_dataContract">Contract contains the custAccount list required per task</param>
    public void processSubTask( METVendOpenItemsContract _dataContract)
    {
        VendOnHoldHistory                   onHoldHistory;
        VendTransOpen                       vendTransOpen;
        VendTrans                           vendTrans;
        VendTable                           vendTable;
        METVendOpenItems                    metVendOpenItems;
        List                                recList                   = new List(Types::Int64);
        ListEnumerator                      enumerator;
        VendParameters                      vendParameters = VendParameters::find();
        

        try
        {
            recList    = _dataContract.getRecList();
            enumerator      = recList.getEnumerator();

            while (enumerator.moveNext())
            {
                
                select firstonly crosscompany 
                    RecId,
                    RefRecID,
                    AccountNum,
                    AmountCur,
                    DueDate,
                    TransDate,
                    DataAreaId
                from VendTransOpen
                    where VendTransOpen.RecId == enumerator.current()
                join Invoice,
                    Approved,
                    PaymMode,
                    CurrencyCode,
                    DocumentDate,
                    JournalNum,
                    DocumentNum,
                    RecId,
                    Voucher,
                    TransDate,
                    DefaultDimension,
                    DataAreaId,
                    InvoiceReleaseDate
                from vendTrans
                    where vendTrans.Recid == vendTransOpen.RefRecID
                    && VendTrans.PaymMode   == vendParameters.METpayPaymMode
                join AccountNum
                from vendTable
                    where vendTable.AccountNum == vendTransOpen.AccountNum
                notexists join onHoldHistory
                    where onHoldHistory.VendAccount == VendTable.AccountNum
                        && (onHoldHistory.onHold == CustVendorBlocked::All
                        || onHoldHistory.onHold == CustVendorBlocked::Payment)
                        // && VendTrans.approved   == NoYes::Yes  Including open items that are not approved (logic explained in initFromVendorTransaction method)
                    ;
                

                if (VendTransOpen && VendTrans && vendTable)
                {
                    LedgerJournalTrans  journalTrans;

                    while select crosscompany journalTrans
                        where journalTrans.Voucher == vendTrans.Voucher &&
                        journalTrans.Company == vendTrans.DataAreaId &&
                        (journalTrans.AccountType == LedgerJournalACType::Ledger ||
                        (journalTrans.AccountType == LedgerJournalACType::Vend && journalTrans.OffsetLedgerDimension))
                    {
                        metVendOpenItems = METVendOpenItems::find(journalTrans.RecId);
                        if (!metVendOpenItems)
                        {
                            this.insertRecord(metVendOpenItems, vendTransOpen, vendTrans, journalTrans);
                        }
                        else if (metVendOpenItems)
                        {
                            this.updateRecord(metVendOpenItems, vendTransOpen, vendTrans, journalTrans);
                        }
                    }
    
                }
            }
        }
        catch (Exception::CLRError)
        {
            //If an error occurs, check if log header is available
            this.getInfologMessage();
            System.Exception ex = CLRInterop::getLastException();
            errorMessage += ex.Message + ex.ToString();            
            info(errorMessage + infologMessage);
            

        }
    }

    /// <summary>
    /// MPJ_5046_MetpayInterfaces 05/05/2021
    /// This method gets the info of the error into a variable
    /// </summary>
    private void getInfologMessage()
    {
        SysInfologEnumerator sysInfologEnumerator;
        SysInfologMessageStruct sysInfologMessageStruct;

        sysInfologEnumerator = SysInfologEnumerator::newData(infolog.infologData());

        while (sysInfologEnumerator.moveNext())
        {
            sysInfologMessageStruct = new SysInfologMessageStruct(sysInfologEnumerator.currentMessage());

            if (sysInfologEnumerator.currentException() == Exception::Error)
            {
                errorMessage += strfmt(sysInfologMessageStruct.message());
            }
            infologMessage += strfmt(sysInfologMessageStruct.message());
        }
    }

    /// <summary>
    /// MPJ_5046_MetpayInterfaces
    /// Setting the fields for update/insert
    /// </summary>
    /// <param name = "_metVendOpenItems">metVendOpenItems table</param>
    /// <param name = "_vendTransOpen">vendtransopen table</param>
    /// <param name = "_vendTrans">vendtrans table</param>
    /// <param name = "_journalTrans"><c>ledgerJournalTrans</c> table</param>
    private void initFromVendorTransaction(METVendOpenItems   _metVendOpenItems,
                                         VendTransOpen      _vendTransOpen,
                                         VendTrans          _vendTrans,
                                         LedgerJournalTrans _journalTrans)
    {
        LedgerJournalTable  ledgerJournalTable = _journalTrans.ledgerJournalTable();

        _metVendOpenItems.AccountNum            = _vendTransOpen.AccountNum;
        _metVendOpenItems.Invoice               = _vendTrans.Invoice;
        _metVendOpenItems.AmountCur             = _journalTrans.amount();
        _metVendOpenItems.DueDate               = _vendTransOpen.DueDate;        
        _metVendOpenItems.JournalName           = ledgerJournalTable.JournalName;
        _metVendOpenItems.DefaultDimension      = _vendTrans.DefaultDimension;
        _metVendOpenItems.GSTAmount             = this.calculateGSTAmount(_journalTrans);
        _metVendOpenItems.Currency              = _vendTrans.CurrencyCode;
        _metVendOpenItems.DocumentDate          = _vendTrans.DocumentDate;
        _metVendOpenItems.TransDate           = _vendTransOpen.TransDate;
        _metVendOpenItems.JournalType           = ledgerJournalTable.JournalType;
        _metVendOpenItems.Document              = _vendTrans.DocumentNum;
        _metVendOpenItems.CompanyCode           = _vendTransOpen.DataAreaId;
        _metVendOpenItems.JournalBatchNumber    = _vendTrans.JournalNum;
        _metVendOpenItems.Description           = _journalTrans.Txt;
        _metVendOpenItems.OffsetTransactionText = _journalTrans.OffsetTxt;
        _metVendOpenItems.Approved              = _vendTrans.Approved;
        _metVendOpenItems.InvoiceReleaseDate    = _vendTrans.InvoiceReleaseDate;
    }

    /// <summary>
    /// MPJ_5046_MetpayInterfaces 05/05/2021
    /// Inserts a record in the table
    /// </summary>
    /// <param name = "_metVendOpenItems">metVendOpenItems table</param>
    /// <param name = "_vendTransOpen">vendtransopen table</param>
    /// <param name = "_vendTrans">vendtrans table</param>
    /// <param name = "_journalTrans"><c>ledgerJournalTrans</c> table</param>
    public void insertRecord(METVendOpenItems   _metVendOpenItems, 
                             VendTransOpen      _vendTransOpen,
                             VendTrans          _vendTrans,
                             LedgerJournalTrans _journalTrans)
    {        
        this.initFromVendorTransaction(_metVendOpenItems, _vendTransOpen, _vendTrans, _journalTrans);

        _metVendOpenItems.LedgerJournalTransRecId   = _journalTrans.RecId;
        _metVendOpenItems.VendTransOpenRecId        = _vendTransOpen.RecId;
        _metVendOpenItems.AckStatus                 = METAckStatus::Blank;
        _metVendOpenItems.RecordStatus              = METRecordStatus::New;
        
        ttsbegin;       
        _metVendOpenItems.insert();
        ttscommit;
    }

/// <summary>
/// MPJ_5046_MetpayInterfaces
/// Update a record in the table
/// </summary>
/// <param name = "_metVendOpenItems">metVendOpenItems table</param>
/// <param name = "_vendTransOpen">vendtransopen table</param>
/// <param name = "_vendTrans">vendtrans table</param>
/// <param name = "_journalTrans"><c>ledgerJournalTrans</c> table</param>
public void updateRecord(METVendOpenItems   _metVendOpenItems,
                         VendTransOpen      _vendTransOpen,
                         VendTrans          _vendTrans,
                         LedgerJournalTrans _journalTrans)
{
    // Ignore the record if Approved = No & AckStatus = Rejected
    if((_vendTrans.Approved == NoYes::Yes && _metVendOpenItems.AckStatus == METAckStatus::Rejected)
        || _metVendOpenItems.AckStatus == METAckStatus::Approved
        || _metVendOpenItems.AckStatus == METAckStatus::Blank)
    {
        if(_metVendOpenItems.AckStatus == METAckStatus::Rejected)
        {
            _metVendOpenItems.AckStatus = METAckStatus::Blank;
        }
        this.initFromVendorTransaction(_metVendOpenItems, _vendTransOpen, _vendTrans, _journalTrans);
        
        if(_metVendOpenItems.orig().AckStatus != _metVendOpenItems.AckStatus
            || _metVendOpenItems.orig().AmountCur != _metVendOpenItems.AmountCur
            || _metVendOpenItems.orig().DueDate != _metVendOpenItems.DueDate
            || _metVendOpenItems.orig().JournalName != _metVendOpenItems.JournalName
            || _metVendOpenItems.orig().DefaultDimension != _metVendOpenItems.DefaultDimension
            || _metVendOpenItems.orig().GSTAmount != _metVendOpenItems.GSTAmount
            || _metVendOpenItems.orig().Currency != _metVendOpenItems.Currency
            || _metVendOpenItems.orig().DocumentDate != _metVendOpenItems.DocumentDate
            || _metVendOpenItems.orig().TransDate != _metVendOpenItems.TransDate
            || _metVendOpenItems.orig().JournalType != _metVendOpenItems.JournalType
            || _metVendOpenItems.orig().Document != _metVendOpenItems.Document
            || _metVendOpenItems.orig().CompanyCode != _metVendOpenItems.CompanyCode
            || _metVendOpenItems.orig().JournalBatchNumber != _metVendOpenItems.JournalBatchNumber
            || _metVendOpenItems.orig().Description != _metVendOpenItems.Description
            || _metVendOpenItems.orig().OffsetTransactionText != _metVendOpenItems.OffsetTransactionText
            || _metVendOpenItems.orig().Approved != _metVendOpenItems.Approved
            || _metVendOpenItems.orig().InvoiceReleaseDate != _metVendOpenItems.InvoiceReleaseDate
            || _metVendOpenItems.orig().Invoice != _metVendOpenItems.Invoice
            || _metVendOpenItems.orig().AccountNum != _metVendOpenItems.AccountNum)
        {
            ttsbegin;
            _metVendOpenItems.selectForUpdate(true);
            
            _metVendOpenItems.AckStatus = METAckStatus::Blank;
            _metVendOpenItems.RecordStatus  = METRecordStatus::New;
            _metVendOpenItems.update();
            ttscommit;
        }
    }
}

    /// <summary>
    /// MPJ_5046_MetpayInterfaces 11/06/2021
    /// Method to return the GST Amount
    /// </summary>
    /// <param name = "_journalTrans"><c>LedgerJournalTrans</c> table</param>
    /// <returns>Tax amount</returns>
    public TaxAmountCur calculateGSTAmount(LedgerJournalTrans _journalTrans)
    {
        TaxAmountCur GSTAmount;
        TaxTrans taxTrans;
        changecompany(_journalTrans.DataAreaId)
        {
            select sum(SourceRegulateAmountCur) from taxTrans
                where taxTrans.Voucher == _journalTrans.Voucher
                && taxTrans.TransDate == _journalTrans.TransDate
                && taxTrans.SourceTableId == _journalTrans.TableId 
                && taxTrans.SourceRecId == _journalTrans.RecId;

            GSTAmount = -taxTrans.SourceRegulateAmountCur;
        }
        return GSTAmount;
    }
